const req = $input.first().json;
const q = req.query || {};
let expected = null;
try { expected = $env.META_VERIFY_TOKEN; } catch (e) { expected = null; }
if (q['hub.mode'] === 'subscribe' && (expected === null || q['hub.verify_token'] === expected)) {
  return [{ json: { respond: String(q['hub.challenge'] || '') } }];
}
throw new Error('Meta webhook verification failed: invalid token');

const req = $input.first().json;
const key = req.headers && req.headers['apikey'];
let expected = null;
try { expected = $env.EVOLUTION_API_KEY; } catch (e) { expected = null; }
if (expected && key !== expected) throw new Error('Invalid Evolution apikey — possible spoofed request');
return [{ json: req }];

const src = $('Normalize Code2').first().json.lead_info;
const FALLBACK = 'تمام يا فندم 🌸 ممكن توضحلي طلب حضرتك تاني؟';

try {
  let rawData = $input.first().json.output || $input.first().json.text;
  rawData = String(rawData).replace(/```json/g, '').replace(/```/g, '').trim();
  const parsedData = JSON.parse(rawData);

  const textCheck = String(parsedData.recommended_action || '') + ' ' + String(parsedData.response_to_customer || '');
  const forceApproval = /log_contract|log_payment|عقد|دفعة|مقدم|قسط/.test(textCheck);
  const requiresApproval = parsedData.requires_human_approval || forceApproval;

  return {
    json: {
      ok: true,
      intent: parsedData.intent || 'UNKNOWN',
      client_id: parsedData.client_id || null,
      matched_property_id: parsedData.matched_property_id || null,
      requirements: parsedData.requirements || {},
      missing_fields: parsedData.missing_fields || [],
      lead_status: parsedData.lead_status || 'NEW',
      requires_human_approval: requiresApproval,
      recommended_action: parsedData.recommended_action || 'UNKNOWN',
      language: parsedData.language || 'ar',
      chat_id: src.external_user_id,
      source: src.source,
      reply: parsedData.response_to_customer || FALLBACK
    }
  };
} catch (error) {
  return {
    json: {
      ok: false,
      error: 'JSON Parsing Failed',
      raw_output: $input.first().json.output || $input.first().json.text,
      requires_human_approval: true,
      recommended_action: 'ESCALATE_TO_BROKER',
      chat_id: src.external_user_id,
      source: src.source,
      reply: FALLBACK
    }
  };
}

