const out = [];

for (const { json: j } of $input.all()) {
  const b = j.body ?? {};
  const wa = b.entry?.[0]?.changes?.[0]?.value;
  const ms = b.entry?.[0]?.messaging?.[0];
  const ev = b.data;
  let lead = null;

  if (j.message?.chat) {
    const m = j.message;
    const f = m.from;
    let media_type = 'unsupported';
    let media_ref = null;
    if (m.text) media_type = 'text';
    else if (m.photo?.length) { media_type = 'image'; media_ref = m.photo.at(-1).file_id; }
    else if (m.voice || m.audio) { media_type = 'voice'; media_ref = (m.voice ?? m.audio).file_id; }
    lead = {
      source: 'telegram',
      external_user_id: String(f.id),
      customer_name: [f.first_name, f.last_name].filter(Boolean).join(' ') || null,
      phone: null,
      language: 'ar',
      media_type,
      media_ref,
      media_url: null,
      raw_message: m.text ?? m.caption ?? '',
    };

  } else if (b.event && ev?.key) {
    if (ev.key.fromMe) continue;
    const jid = ev.key.remoteJid ?? '';
    const msg = ev.message ?? {};
    let media_type = null;
    let media_ref = null;
    let caption = '';
    if (msg.imageMessage) { media_type = 'image'; media_ref = ev.key.id; caption = msg.imageMessage.caption ?? ''; }
    else if (msg.audioMessage) { media_type = 'voice'; media_ref = ev.key.id; }
    lead = {
      source: 'whatsapp',
      external_user_id: jid.split('@')[0],
      customer_name: ev.pushName ?? null,
      phone: jid.endsWith('@s.whatsapp.net') ? `+${jid.split('@')[0]}` : null,
      language: 'ar',
      media_type,
      media_ref,
      media_url: null,
      raw_message: msg.conversation ?? msg.extendedTextMessage?.text ?? caption,
    };

  } else if (wa?.messages?.[0]) {
    const m = wa.messages[0];
    lead = {
      source: 'whatsapp',
      external_user_id: m.from,
      customer_name: wa.contacts?.[0]?.profile?.name ?? null,
      phone: `+${m.from}`,
      language: 'ar',
      media_type: null,
      media_ref: null,
      media_url: null,
      raw_message: m.text?.body ?? '',
    };

  } else if (ms?.message && !ms.message.is_echo) {
    const att = ms.message.attachments?.[0];
    let media_type = null;
    let media_url = null;
    if (att?.type === 'image' && !att.payload?.sticker_id) { media_type = 'image'; media_url = att.payload?.url ?? null; }
    else if (att?.type === 'audio') { media_type = 'voice'; media_url = att.payload?.url ?? null; }
    lead = {
      source: b.object === 'instagram' ? 'instagram' : 'messenger',
      external_user_id: ms.sender.id,
      customer_name: null,
      phone: null,
      language: 'ar',
      media_type,
      media_ref: null,
      media_url,
      raw_message: ms.message.text ?? '',
    };
  }

  if (lead) {
    lead.media_type ??= lead.raw_message ? 'text' : 'unsupported';
    out.push({ json: { lead_info: lead } });
  } else {
    console.log('UNMATCHED:', JSON.stringify(j).slice(0, 800));
  }
}

return out;

const lead = $('Normalize Code2').first().json.lead_info;
const media = $input.first().json.media_text ?? null;

const label =
  lead.media_type === 'image' ? '[العميل بعت صورة] ' :
  lead.media_type === 'voice' ? '[رسالة صوتية من العميل] ' : '';

const parts = [lead.raw_message, media ? label + media : null].filter(Boolean);

return [{ json: { lead_info: { ...lead, raw_message: parts.join('\n') } } }];

const items = $input.all().map(i => i.json);
const by = k => (items.find(i => i.key === k) || {}).rows || [];
const clients = by('clients');
const properties = by('properties');
const brokers = by('brokers');
const inquiries = by('inquiries');
const appointments = by('appointments');
const contracts = by('contracts');
const payments = by('payments');

const brokersOut = brokers.map(b => {
  const closed = contracts.filter(c => String(c.employee_id) === String(b.id) && String(c.status).toLowerCase() === 'completed');
  const value = closed.reduce((s,c) => s + (Number(c.total_price)||0), 0) / 1000000;
  return { ...b, closed: closed.length, value: Math.round(value*10)/10, appts: 0 };
});

const revenueByMonth = {};
contracts.forEach(c => {
  const d = new Date(c.contract_date); if (isNaN(d)) return;
  const key = d.toLocaleString('en-US', { month: 'short' });
  revenueByMonth[key] = revenueByMonth[key] || { rent: 0, sale: 0 };
  const amt = (Number(c.total_price)||0) / 1000000;
  if (String(c.contract_type).toLowerCase() === 'rent') revenueByMonth[key].rent += amt; else revenueByMonth[key].sale += amt;
});

const leadFunnel = {};
clients.forEach(c => { const s = c.status || 'NEW'; leadFunnel[s] = (leadFunnel[s]||0) + 1; });

const leadsBySource = {};
clients.forEach(c => { const s = c.source || 'unknown'; leadsBySource[s] = (leadsBySource[s]||0) + 1; });

return [{ json: {
  clients, properties, brokers: brokersOut, inquiries, appointments, contracts, payments,
  errors: [],
  charts: { revenueByMonth, leadFunnel, leadsBySource }
} }];

const item = $input.first().json;
const signature = item.headers && item.headers['x-hub-signature-256'];

let secret = null;
try { secret = $env.META_APP_SECRET; } catch (e) { secret = null; }

if (secret) {
  if (!signature) throw new Error('Missing X-Hub-Signature-256 header — request rejected');
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey('raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  const sigBuf = await crypto.subtle.sign('HMAC', key, enc.encode(JSON.stringify(item.body)));
  const hex = Array.from(new Uint8Array(sigBuf)).map(b => b.toString(16).padStart(2,'0')).join('');
  const expected = 'sha256=' + hex;
  if (signature !== expected) throw new Error('Invalid Meta signature — possible spoofed request');
}
return [{ json: { headers: item.headers, params: item.params, query: item.query, body: item.body } }];

